import{api,get,post,put,patch}from'./api.js';
import{state,basket,money,total,subtotal}from'./store.js';
import{modules,current}from'./router.js';
import{installKeyboard}from'./keyboard.js';
import{toast}from'./toast.js';
const root=document.querySelector('#app');let searchTimer=null,unmountKeyboard=null,searchResults=[],lastView='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(o,...keys)=>{for(const k of keys){const v=o?.[k];if(v!==undefined&&v!==null&&v!=='')return v;}return '—';};
const fmtDate=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString('fr-FR');};
const rowsOf=d=>Array.isArray(d)?d:(Array.isArray(d?.list)?d.list:(Array.isArray(d?.data)?d.data:[]));
function focusSearch(){document.querySelector('#barcode-search')?.focus();}
function pageTitle(){return current(state).label;}
function layout(content){document.documentElement.dataset.theme=state.theme;const m=current(state);root.innerHTML=`<div class="shell ${state.expanded?'expanded':''}"><aside class="rail"><div class="brand"><span class="mark">SM</span><span class="brand-name">Saint Marina POS<br><small class="muted">POSNIC Next</small></span></div><nav class="nav">${modules.map(x=>`<button data-view="${x.id}" class="${state.view===x.id?'active':''}" title="${esc(x.label)}"><span class="ico">${x.icon}</span><span class="nav-label">${esc(x.label)}</span></button>`).join('')}</nav><div class="rail-bottom"><span class="small muted"><i class="online"></i> Connecté</span><button data-action="companion"><span class="ico">▣</span><span class="nav-label" id="companion-count">Samarina Companion · ${state.connectedPhones}</span></button><button data-action="theme"><span class="ico">◐</span><span class="nav-label">${state.theme==='dark'?'Mode clair':'Mode sombre'}</span></button><button data-view="parametres"><span class="ico">⚙</span><span class="nav-label">Paramètres</span></button><button data-action="collapse"><span class="ico">⇔</span><span class="nav-label">Réduire le menu</span></button></div></aside><header class="topbar"><div class="crumb">${esc(m.label)} <span class="muted">/ ${esc(m.tabs[state.tab]||m.tabs[0])}</span></div><div class="top-actions"><input id="global-search" class="field" placeholder="Rechercher · Ctrl K" aria-label="Recherche globale"><span>${esc(state.user?.name||state.user?.username||state.user?.email||'Caissier')}</span><span id="clock"></span></div></header><main>${content}</main></div>${state.drawer?drawerHtml():''}`;
 document.querySelector('#clock').textContent=new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
}
function head(title,subtitle='',action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><div class="muted">${esc(subtitle)}</div></div>${action}</div>`;}
function tabbar(){return `<div class="tabs">${current(state).tabs.map((t,i)=>`<button class="tab ${i===state.tab?'active':''}" data-tab="${i}">${esc(t)}</button>`).join('')}</div>`;}
function table(data,cols){const list=rowsOf(data);if(!list.length)return '<div class="empty">Aucun résultat pour ces critères.</div>';return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${list.map(row=>`<tr data-cart-row>${cols.map(c=>`<td>${c.render?c.render(row):esc(val(row,...c.keys))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function drawerHtml(){const d=state.drawer;return `<div class="drawer-backdrop" data-action="backdrop"><section class="drawer" role="dialog" aria-modal="true"><div class="drawer-head"><h2>${esc(d.title)}</h2><button class="btn" data-action="close">Fermer ×</button></div>${d.html}</section></div>`;}
function login(){layout(`<section class="panel login"><div class="brand"><span class="mark">SM</span><strong>Saint Marina Life</strong></div><h1>Connexion</h1><p class="muted">Connectez-vous avec votre compte POSNIC.</p><form id="login-form" class="form-grid"><div class="form-field full"><label>Nom d’utilisateur ou e-mail</label><input class="field" name="username" autocomplete="username" required></div><div class="form-field full"><label>Mot de passe</label><input class="field" type="password" name="password" autocomplete="current-password" required></div><div class="form-field full"><button class="btn primary" type="submit">Se connecter</button></div></form></section>`);}
async function checkSession(){try{state.user=await get('auth/me');return true;}catch{return false;}}
async function loadProducts(q=''){const d=await get('items/fast-search',{q,limit:40,page:1});return rowsOf(d);}
function addItem(item,quantity=1){const b=basket();const id=String(item._id||item.id),amount=Math.max(1,Number(quantity)||1);const found=b.items.find(x=>String(x._id)===id);if(found){const available=Number(found.available_quantity);if(found.track_inventory&&!found.negative_stock&&Number.isFinite(available)&&found.quantity+amount>available){toast('Stock insuffisant pour cet article.','error');return false;}found.quantity+=amount;}else{if(item.track_inventory&&!item.negative_stock&&Number(item.available_quantity)<amount){toast('Stock insuffisant pour cet article.','error');return false;}b.items.push({...item,_id:id,quantity:amount});}render();return true;}
function cashier(){const b=basket();const sum=total();return head('Caisse','Vente rapide · scanner, rechercher et encaisser',`<button class="btn" data-action="new-basket">＋ Nouveau [F6]</button>`)+`<div class="basket-tabs">${state.baskets.map(x=>`<button class="basket-tab ${x.id===state.activeBasket?'active':''}" data-basket="${x.id}">${esc(x.name)} · ${x.items.length}</button>`).join('')}<button class="basket-tab" data-action="new-basket">＋</button></div><div class="checkout"><section><div class="panel"><div class="toolbar"><input id="barcode-search" class="field search" placeholder="Scanner code-barres / rechercher un article" autocomplete="off"><span class="muted small">Recherche serveur · 120 ms · Samarina : <span id="mobile-sync-status">${esc(state.mobileSync)}</span></span></div><div id="product-results" class="quick-grid"></div></div><div class="panel"><h3>Articles du panier</h3>${b.items.length?table(b.items,[{label:'Article',keys:['name']},{label:'Prix unitaire',render:r=>money(r.selling_price)+' DZD'},{label:'Qté',render:r=>`<button class="btn" data-qty="-1" data-id="${esc(r._id)}">−</button> <b>${r.quantity}</b> <button class="btn" data-qty="1" data-id="${esc(r._id)}">＋</button>`},{label:'Total',render:r=>money((Number(r.selling_price)||0)*r.quantity)+' DZD'},{label:'',render:r=>`<button class="btn" data-remove="${esc(r._id)}">Supprimer</button>`}]) : '<div class="empty">Scannez un code-barres ou choisissez un article pour commencer.</div>'}</div></section><aside><div class="panel"><h3>Client</h3><div>${esc(b.customer?.name||'Client de passage')}</div><p class="muted">Crédit : ${money(b.customer?.debt||0)} DZD</p><button class="btn" data-action="customer">Choisir un client [F3]</button></div><div class="panel checkout-card"><div class="muted">Articles : ${b.items.reduce((s,x)=>s+x.quantity,0)}</div><div class="muted">Sous-total : ${money(sum)} DZD</div><div class="checkout-total">${money(sum)} <small>DZD</small></div><div class="actions"><button class="btn primary" data-action="F1" ${b.items.length?'':'disabled'}>Encaisser espèces <span class="hotkey">F1</span></button><button class="btn" data-action="F2" ${b.items.length?'':'disabled'}>Multi-paiement / Crédit <span class="hotkey">F2</span></button></div></div><div class="panel"><div class="actions"><button class="btn" data-action="F4">Remise [F4]</button><button class="btn" data-action="F7">ZR Express [F7]</button><button class="btn" data-action="F8">Retour / échange [F8]</button></div></div></aside></div>`;}
async function moduleContent(){const id=state.view,tab=state.tab;const tabs=current(state).tabs;let data=[],cols=[],subtitle='Données POSNIC en direct';
 if(id==='catalogue'&&tab===0){data=await get('items/fast-search',{limit:40,page:state.page,q:state.query});cols=[{label:'Article',keys:['name']},{label:'SKU',keys:['itemid']},{label:'Code-barres',keys:['barcode_id']},{label:'Catégorie',keys:['category_name']},{label:'Marque',keys:['brand']},{label:'Prix vente',render:r=>money(r.selling_price)+' DZD'},{label:'Stock',keys:['available_quantity']},{label:'Actions',render:r=>`<button class="btn" data-queue-label="${esc(r._id)}">Étiquette</button> <button class="btn" data-edit-item="${esc(r._id)}">Modifier</button>`}];}
 else if(id==='catalogue'&&tab===1){data=await get('stock-logs',{limit:40,page:1});cols=[{label:'Date',render:r=>fmtDate(val(r,'createdAt','created_date','date'))},{label:'Article',keys:['item_name','name']},{label:'Type',keys:['type','stock_type']},{label:'Variation',keys:['quantity','variation']},{label:'Stock après',keys:['stock_after','available_quantity']},{label:'Utilisateur',keys:['user_name','created_by']}];}
 else if(id==='catalogue'&&tab===2){data=await get('items/itemLowStockTable',{limit:40,page:1});cols=[{label:'Article',keys:['name']},{label:'SKU',keys:['itemid']},{label:'Fournisseur',keys:['supplier_name']},{label:'Stock',keys:['available_quantity']},{label:'Seuil',keys:['low_stock_alert','reorder_point']}];}
 else if(id==='catalogue'&&tab===3){return await labelDesigner();}
 else if(id==='achats'&&tab===0){const [suppliers,products]=await Promise.all([get('suppliers',{limit:100,page:1}),get('items/fast-search',{limit:40,page:1})]);return purchaseForm(suppliers,products);}
 else if(id==='achats'&&tab===1){data=await get('receivings',{limit:40,page:1});cols=[{label:'Référence',keys:['receiving_number','invoice_number','reference']},{label:'Fournisseur',keys:['supplier_name']},{label:'Date',render:r=>fmtDate(val(r,'createdAt','created_date','date'))},{label:'Total',render:r=>money(val(r,'total','grand_total'))+' DZD'},{label:'Statut',keys:['status']}];}
 else if(id==='clients'&&tab===0){data=await get('customers',{limit:40,page:1});cols=[{label:'Client',keys:['name','customer_name']},{label:'Téléphone',keys:['phone','customer_phone']},{label:'Ville',keys:['city','state']},{label:'Crédit',render:r=>money(val(r,'outstanding','balance','credit'))+' DZD'},{label:'Actions',render:r=>`<button class="btn" data-remind="${esc(r._id)}">Relance WhatsApp</button>`}];}
 else if(id==='clients'&&tab===1){data=await get('credit/outstanding',{limit:40,page:1});cols=[{label:'Client',keys:['customer_name','name']},{label:'Téléphone',keys:['phone','customer_phone']},{label:'Dette',render:r=>money(val(r,'outstanding','balance','payment_pending'))+' DZD'},{label:'Actions',render:r=>`<button class="btn" data-settle="${esc(r.customer_id||r._id)}">Encaisser versement</button> <button class="btn" data-remind="${esc(r.customer_id||r._id)}">WhatsApp</button>`}];}
 else if(id==='clients'&&tab===2){data=await get('sales',{limit:40,page:1});cols=[{label:'Ticket',keys:['sales_id','sale_number']},{label:'Date',render:r=>fmtDate(val(r,'date','createdAt'))},{label:'Client',keys:['customer_name']},{label:'Total',render:r=>money(r.sales_total)+' DZD'},{label:'Paiement',keys:['payment_mode','payment_status']},{label:'Statut',keys:['sale_status','status']},{label:'Actions',render:r=>`<button class="btn" data-whatsapp-sale="${esc(r.sales_id||r._id)}" data-phone="${esc(r.customer_phone||'')}">WhatsApp</button> <button class="btn" data-print-sale="${esc(r._id)}">Réimprimer</button>`}];}
 else if(id==='zr-express'&&tab===0){data=await get('delivery-zr',{limit:40,page:1});cols=[{label:'Suivi',keys:['tracking_number','tracking','id']},{label:'Client',keys:['recipient_name','customer_name']},{label:'Téléphone',keys:['recipient_phone','phone']},{label:'Statut',keys:['status']},{label:'COD',render:r=>money(val(r,'cod_total','amount'))+' DZD'},{label:'Action',render:r=>`<button class="btn" data-zr-status="${esc(r.tracking_number||r.tracking)}">Marquer livré</button>`}];}
 else if(id==='zr-express'&&tab===1){return zrCreateForm();}
 else if(id==='rapports'&&tab===0){const today=new Date().toISOString().slice(0,10),branch=state.user?.branch_id||state.user?.branch?._id||state.user?.default_branch_id;data=await get('sales/cashierDaySummary',{branch,starting_date:today,ending_date:today,type:'VIEW'});return reportView(data,today);}
 else if(id==='rapports'&&tab===1){const filter=state.dashboardFilter||'day';const [totals,profit,bestsellers,purchases]=await Promise.all([get('dashboard/getDashboardTotalAmounts',{filter}),get('dashboard/getProfitSummary',{filter}),get('dashboard/getDashboardBestSellingProducts',{filter}),get('dashboard/getDashboardSalesPurchase',{filter})]);return dashboardView({totals,profit,bestsellers,purchases,filter});}
 else if(id==='rapports'&&tab===2){data=await get('sales',{limit:100,page:1});return calendarView(rowsOf(data));}
 else if(id==='rapports'&&tab===3){data=await get('receivings/summary');return genericData(data,'Achats & marges');}
 else if(id==='parametres'){return settingsView();}
 else {return genericData([],tabs[tab]);}
 state.records=rowsOf(data);return head(tabs[tab],subtitle,`<button class="btn" data-action="refresh">Actualiser</button> ${id==='clients'&&tab===0?'<button class="btn primary" data-action="new-customer">＋ Nouveau client</button>':''} ${id==='catalogue'&&tab===0?'<button class="btn primary" data-action="new-item">＋ Nouvel article</button>':''}`)+`<div class="toolbar"><input id="list-search" class="field search" placeholder="Rechercher dans cette liste" value="${esc(state.query)}"><span class="muted small">40 lignes par page</span></div>${table(data,cols)}`;
}
async function labelDesigner(){const t=await get('posnic-next/settings/label-template');return head('Designer d’Étiquettes','Modèle de prix persistant · aperçu et impression thermique')+`<div class="panel"><div class="form-grid"><div class="form-field"><label>Nom de l’article</label><input class="field" id="label-name"></div><div class="form-field"><label>Prix DZD</label><input class="field" id="label-price" type="number" min="0"></div><div class="form-field"><label>Largeur (mm)</label><input class="field" id="label-width" type="number" value="${Number(t.width)||30}"></div><div class="form-field"><label>Hauteur (mm)</label><input class="field" id="label-height" type="number" value="${Number(t.height)||45}"></div><div class="form-field"><label>Code-barres / référence</label><input class="field" id="label-code"></div><div class="form-field"><label>Copies</label><input class="field" id="label-copies" type="number" min="1" value="${Number(t.copies)||1}"></div><div class="form-field"><label><input type="checkbox" id="label-show-name" ${t.showName!==false?'checked':''}> Nom</label></div><div class="form-field"><label><input type="checkbox" id="label-show-price" ${t.showPrice!==false?'checked':''}> Prix</label></div><div class="form-field"><label><input type="checkbox" id="label-show-barcode" ${t.showBarcode!==false?'checked':''}> Code-barres</label></div></div><p class="actions"><button class="btn" data-action="save-label-template">Enregistrer le modèle</button><button class="btn primary" data-action="print-label">Imprimer les étiquettes</button></p><div class="panel"><b>File d’impression : ${state.labelQueue.length} article(s)</b><div class="small muted">${state.labelQueue.map(x=>esc(x.name)).join(' · ')||'Aucun article ajouté depuis le catalogue.'}</div><button class="btn" data-action="clear-label-queue">Vider la file</button></div><div id="label-preview" class="panel">Aperçu d’étiquette</div></div>`;}
function purchaseForm(suppliers,products){const list=rowsOf(suppliers),items=rowsOf(products);return head('Nouvelle Réception / Facture','Créer une réception et faire entrer les quantités dans le stock POSNIC')+`<form id="receiving-form" class="panel form-grid"><div class="form-field"><label>Fournisseur</label><select class="field" name="supplier_id" required><option value="">Sélectionner</option>${list.map(x=>`<option value="${esc(x._id)}" data-name="${esc(val(x,'name','supplier_name'))}" data-address="${esc(val(x,'address','supplier_address'))}" data-phone="${esc(val(x,'phone','supplier_phone'))}">${esc(val(x,'name','supplier_name'))}</option>`).join('')}</select></div><div class="form-field"><label>Référence facture</label><input class="field" name="invoice_number"></div><div class="form-field"><label>Date</label><input class="field" name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></div><div class="form-field"><label>Mode de paiement</label><select class="field" name="payment_mode"><option value="Cash">Espèces</option><option value="Credit">Crédit fournisseur</option><option value="Bank Transfer">Virement</option></select></div><div class="form-field full"><label>Article reçu</label><select class="field" name="item_id" required><option value="">Choisir un article</option>${items.map(x=>`<option value="${esc(x._id)}">${esc(x.name)} · ${esc(x.itemid||'')} · ${money(x.company_price)} DZD</option>`).join('')}</select></div><div class="form-field"><label>Quantité reçue</label><input class="field" name="item_quantity" type="number" min=".001" step=".001" value="1" required></div><div class="form-field"><label>Taxe (%)</label><input class="field" name="item_tax" type="number" min="0" step=".01" value="0"></div><div class="form-field full"><label>Note / référence facture</label><input class="field" name="payment_description"></div><div class="form-field full"><button class="btn primary">Enregistrer réception et mouvement de stock</button></div></form>`;}
async function zrCreateForm(){const bridge=window.electronAPI?.zr;if(!bridge)return head('Créer un Colis','ZR Express est disponible dans la version desktop.')+'<div class="panel">Le pont ZR Express Electron est indisponible dans ce navigateur.</div>';let credentials,catalog;try{credentials=await bridge.getCredentials();if(credentials)catalog=await bridge.catalog(credentials);}catch(e){return head('Créer un Colis','Configuration ZR Express')+`<div class="panel danger">${esc(e.message)}</div>`;}if(!credentials)return head('Créer un Colis','Configurez les identifiants ZR Express dans Paramètres → ZR Express API.')+`<div class="panel"><button class="btn" data-view="parametres">Ouvrir les paramètres</button></div>`;state.zrCatalog=catalog;const saleItems=basket().items;return head('Créer un Colis','Créer le colis chez ZR Express puis le rattacher à une vente POSNIC')+`<form id="zr-form" class="panel form-grid"><div class="form-field"><label>ID de vente POSNIC</label><input class="field" name="saleId" placeholder="Identifiant MongoDB ou numéro de ticket" required></div><div class="form-field"><label>Nom destinataire</label><input class="field" name="customerName" required></div><div class="form-field"><label>Téléphone</label><input class="field" name="phone" required></div><div class="form-field"><label>Wilaya</label><select class="field" name="cityTerritoryId" id="zr-wilaya" required><option value="">Choisir</option>${(catalog.wilayas||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.code+' — '+x.name)}</option>`).join('')}</select></div><div class="form-field"><label>Commune</label><select class="field" name="districtTerritoryId" id="zr-commune" required><option value="">Choisir la wilaya d’abord</option></select></div><div class="form-field"><label>Mode de livraison</label><select class="field" name="deliveryType"><option value="home">Domicile</option><option value="pickup-point">Stop desk / bureau</option></select></div><div class="form-field"><label>Point relais (si Stop desk)</label><select class="field" name="sourceHubId"><option value="">Choisir un bureau</option>${(catalog.hubs||[]).filter(x=>x.isPickupPoint).map(x=>`<option value="${esc(x.id)}">${esc(x.name+' · '+x.commune)}</option>`).join('')}</select></div><div class="form-field"><label>Frais de livraison (DZD)</label><input class="field" name="deliveryFee" type="number" min="0" value="0"></div><div class="form-field"><label>Montant COD (DZD)</label><input class="field" name="codTotal" type="number" min="0" max="150000" required></div><div class="form-field full"><label>Adresse</label><input class="field" name="address" required></div><div class="form-field full"><label>Description</label><input class="field" name="description"></div><div class="form-field full"><button class="btn primary">Créer le colis ZR Express et lier à la vente</button></div></form>`;}
function reportView(d,date=new Date().toISOString().slice(0,10)){const x=d||{};const fields=Object.entries(x).filter(([,v])=>['string','number'].includes(typeof v));return head('Clôture de Caisse (Z-Report)','Résumé serveur POSNIC · rapprochement calculé à la confirmation')+`<div class="stats">${fields.slice(0,8).map(([k,v])=>`<div class="stat"><div class="label">${esc(k.replace(/_/g,' '))}</div><div class="value">${typeof v==='number'?money(v):esc(v)}</div></div>`).join('')}</div><div class="panel"><h3>Comptage des billets</h3><form id="close-form" class="form-grid"><input type="hidden" name="date" value="${esc(date)}">${[2000,1000,500,200,100].map(v=>`<div class="form-field"><label>${v} DZD · nombre</label><input class="field denomination" name="denom_${v}" type="number" min="0" step="1" value="0"></div>`).join('')}<div class="form-field full"><strong>Total compté : <span id="counted-cash">0,00</span> DZD</strong></div><div class="form-field full"><button class="btn primary">Clôturer la caisse et enregistrer le Z-Report</button></div></form></div>`;}
function dashboardView(d){const flatten=(value)=>value?.data??value??{};const a=flatten(d.totals),b=flatten(d.profit),p=flatten(d.purchases),top=rowsOf(d.bestsellers);const cards=[...Object.entries(a),...Object.entries(b),...Object.entries(p)].filter(([,v])=>['string','number'].includes(typeof v)).slice(0,12);return head('Tableau de Bord & Statistiques','Indicateurs calculés par les contrôleurs POSNIC')+`<div class="toolbar"><select class="field" id="dashboard-filter"><option value="day" ${d.filter==='day'?'selected':''}>Aujourd’hui</option><option value="week" ${d.filter==='week'?'selected':''}>7 jours</option><option value="month" ${d.filter==='month'?'selected':''}>30 jours</option><option value="year" ${d.filter==='year'?'selected':''}>Année</option></select></div><div class="stats">${cards.map(([k,v])=>`<div class="stat"><div class="label">${esc(k.replace(/_/g,' '))}</div><div class="value">${typeof v==='number'?money(v):esc(v)}</div></div>`).join('')}</div><h3>Meilleures ventes</h3>${table(top,[{label:'Article',keys:['name','item_name']},{label:'Quantité',keys:['quantity','total_quantity']},{label:'Chiffre d’affaires',render:r=>money(val(r,'sales_total','total','amount'))+' DZD'}])}`;}
function calendarView(sales){const days={};for(const s of sales){const key=String(s.date||s.createdAt||'').slice(0,10);if(!key)continue;days[key]=(days[key]||0)+(Number(s.sales_total)||0);}return head('Calendrier des Ventes','Jours et chiffre d’affaires observés dans l’historique chargé')+`<div class="table-wrap"><table><thead><tr><th>Date</th><th>CA DZD</th></tr></thead><tbody>${Object.entries(days).sort((a,b)=>b[0].localeCompare(a[0])).map(([d,v])=>`<tr><td>${esc(d)}</td><td>${money(v)}</td></tr>`).join('')||'<tr><td colspan="2">Aucune vente dans la période chargée.</td></tr>'}</tbody></table></div>`;}
function genericData(d,title){const obj=Array.isArray(d)?d:[d];return head(title,'Réponse du service POSNIC')+`<div class="panel"><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(obj,null,2))}</pre></div>`;}
async function settingsView(){const s=current(state).tabs;const i=state.tab;let data={};if(i===0)data=await get('settings/getThemeSettings');if(i===1)data=await get('posnic-next/settings/costing');if(i===2){const bridge=window.electronAPI?.printer;const [printers,def,receipt]=await Promise.allSettled([bridge?.list?.()||[],bridge?.getDefault?.()||null,bridge?.getReceiptSettings?.()||{}]);data={printers:printers.status==='fulfilled'?printers.value:[],defaultPrinter:def.status==='fulfilled'?def.value:null,receipt:receipt.status==='fulfilled'?receipt.value:{}};}if(i===3){const [status,qr,template]=await Promise.allSettled([get('whatsapp/getStatus'),get('whatsapp/getQRCode'),get('settings/getWhatsAppReceipt')]);data={status:status.status==='fulfilled'?status.value:status.reason?.message,qr:qr.status==='fulfilled'?qr.value:qr.reason?.message,template:template.status==='fulfilled'?template.value:template.reason?.message};}if(i===4){try{data=await window.electronAPI?.zr?.getCredentials?.()||{};}catch(e){data={error:e.message};}}if(i===5){const [devices,backups]=await Promise.allSettled([get('handsets'),window.electronAPI?.backup?.listBackups?.()||[]]);data={devices:devices.status==='fulfilled'?devices.value:[],backups:backups.status==='fulfilled'?backups.value:[]};}return head(s[i],'Configuration persistée par les services POSNIC')+`<div class="settings"><div class="panel settings-nav">${s.map((x,j)=>`<button class="btn ${i===j?'primary':''}" data-tab="${j}">${esc(x)}</button>`).join('')}</div><div class="panel"><h2>${esc(s[i])}</h2>${i===0?generalSettings(data):i===1?costingSettings(data):i===2?printerSettings(data):i===3?whatsappSettings(data):i===4?zrSettings(data):i===5?backupSettings(data):generalSettings()}</div></div>`;}
function generalSettings(){return `<form id="general-settings-form" class="form-grid"><div class="form-field"><label>Nom de la boutique</label><input class="field" name="store_name" value="Saint Marina Life" required></div><div class="form-field"><label>E-mail boutique</label><input class="field" name="store_email" type="email" required></div><div class="form-field"><label>Téléphone boutique</label><input class="field" name="store_telephone" required></div><div class="form-field"><label>Téléphone secondaire</label><input class="field" name="store_alternativephone"></div><div class="form-field full"><label>Adresse boutique</label><input class="field" name="store_address" value="Bordj Bou Arreridj" required></div><div class="form-field full"><label>Adresse imprimée sur ticket</label><input class="field" name="printing_address" value="Bordj Bou Arreridj" required></div><div class="form-field"><label>Thème par défaut</label><select class="field" name="theme"><option value="light">Clair</option><option value="dark">Sombre</option></select></div><div class="form-field full"><button class="btn primary">Enregistrer la boutique et le thème</button></div></form>`;}
function printerSettings(d){const list=Array.isArray(d.printers)?d.printers:[];return `<form id="printer-form" class="form-grid"><div class="form-field full"><label>Imprimante par défaut</label><select class="field" name="printer">${list.map(x=>{const name=typeof x==='string'?x:(x.name||x.displayName||'');return `<option value="${esc(name)}" ${name===(d.defaultPrinter?.name||d.defaultPrinter)?'selected':''}>${esc(name)}</option>`;}).join('')}</select></div><div class="form-field full"><button class="btn primary">Définir imprimante</button> <button type="button" class="btn" data-action="test-printer">Test ticket ESC/POS</button></div></form><pre class="muted small">${esc(JSON.stringify(d.receipt||{},null,2))}</pre>`;}
function zrSettings(d){return `<form id="zr-settings-form" class="form-grid"><div class="form-field full"><label>Tenant ID</label><input class="field" name="tenantId" value="${esc(d.tenantId||'')}" required></div><div class="form-field full"><label>API Key</label><input class="field" name="apiKey" type="password" value="${esc(d.apiKey||'')}" required></div><div class="form-field full"><button class="btn primary">Enregistrer dans le stockage sécurisé</button> <button type="button" class="btn" data-action="test-zr">Tester catalogue & tarifs</button></div></form>`;}
function backupSettings(d){return `<div class="actions"><button class="btn primary" data-action="backup-now">Créer une sauvegarde MongoDB</button></div><h3>Appareils Samarina</h3>${handsetSettings(d.devices||[])}<h3>Sauvegardes disponibles</h3>${genericData(d.backups||[],'Sauvegardes locales')}`;}
function whatsappSettings(d){return `<p>État WhatsApp : <b>${esc(JSON.stringify(d.status))}</b></p><p>QR / appairage : <span class="muted">${esc(JSON.stringify(d.qr))}</span></p><pre style="white-space:pre-wrap">${esc(JSON.stringify(d.template,null,2))}</pre><form id="whatsapp-send" class="form-grid"><div class="form-field"><label>Numéro destinataire</label><input class="field" name="phone" required></div><div class="form-field full"><label>Message de test / relance</label><textarea class="field" name="message" required></textarea></div><div class="form-field full"><button class="btn primary">Envoyer via WhatsApp</button></div></form>`;}
function handsetSettings(d){const list=rowsOf(d);return table(list,[{label:'Appareil',keys:['name','device_name']},{label:'Téléphone',keys:['phone','phone_number']},{label:'État',keys:['status']},{label:'Action',render:r=>`<button class="btn" data-revoke="${esc(r._id||r.device_id)}">Révoquer</button>`}]);}
function returnSaleForm(sale){const lines=Array.isArray(sale.items)?sale.items:[];return `<p class="muted">Ticket ${esc(sale.sales_id||sale.sale_number||sale._id)} · ${esc(sale.customer_name||'Client de passage')} · ${money(sale.sales_total)} DZD</p><form id="return-form" class="form-grid"><div class="form-field full"><div class="table-wrap"><table><thead><tr><th>Article</th><th>Qté vendue</th><th>Prix</th><th>Qté retour</th></tr></thead><tbody>${lines.map((x,i)=>`<tr><td>${esc(x.item_name||x.name)}</td><td>${Number(x.item_quantity)||0}</td><td>${money(x.item_price)} DZD</td><td><input class="field" name="return_qty_${i}" type="number" min="0" max="${Number(x.item_quantity)||0}" step=".001" value="0" style="width:90px"></td></tr>`).join('')}</tbody></table></div></div><div class="form-field"><label>Mode de remboursement</label><select class="field" name="refund_method"><option value="cash">Espèces</option><option value="baridimob">BaridiMob / CCP</option><option value="tpe">TPE</option></select></div><div class="form-field"><label>Motif</label><input class="field" name="reason" required></div><div class="form-field full"><button class="btn primary">Valider le retour et réintégrer le stock</button></div></form>`;}
function paymentDrawer(){const b=basket(),sum=total();state.drawer={title:'Multi-paiement / Crédit',html:`<form id="checkout-form" data-split="true" class="form-grid"><div class="form-field full"><label>Total à payer</label><strong class="checkout-total">${money(sum)} DZD</strong></div><div class="form-field"><label>Espèces (DZD)</label><input class="field" name="cash" type="number" min="0" step=".01" value="${sum}"></div><div class="form-field"><label>BaridiMob / CCP (DZD)</label><input class="field" name="baridimob" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>TPE (DZD)</label><input class="field" name="tpe" type="number" min="0" step=".01" value="0"></div><div class="form-field full"><p>Solde à crédit automatique : sélectionnez un client avant de valider si le paiement est partiel.</p><button type="button" class="btn" data-action="customer">Choisir un client [F3]</button><span class="muted">${esc(b.customer?.name||'Aucun client sélectionné')}</span></div><div class="form-field full"><button class="btn primary">Valider le paiement et enregistrer la vente</button></div></form>`};render();}
async function checkout(form){const b=basket(),sum=total(),fd=new FormData(form),split=form.dataset.split==='true';let payments={},method='Cash',paid=0;if(split){for(const [field,key] of [['cash','Cash'],['baridimob','BaridiMob'],['tpe','TPE']]){const amount=Math.max(0,Number(fd.get(field))||0);if(amount>0)payments[key]=amount;paid+=amount;}method=Object.keys(payments)[0]||'Credit';}else{method=String(fd.get('method')||'Cash');paid=Math.max(0,Number(fd.get('paid'))||0);if(paid>0)payments[method]=paid;}if(!b.items.length)throw new Error('Le panier est vide.');if(paid>sum+.01)throw new Error('Le montant reçu dépasse le total.');const credit=Math.max(0,Math.round((sum-paid)*100)/100);if(credit>0&&!b.customer)throw new Error('Sélectionnez un client enregistré pour accorder un crédit.');const items=b.items.map(x=>({item_id:x._id,item_name:x.name,item_quantity:x.quantity,item_unit:'qty',sale_inline_item_price:Number(x.selling_price)||0,item_price_total:Number(x.selling_price)||0,total_amount:Math.round((Number(x.selling_price)||0)*x.quantity*100)/100,item_available_quantity:Number(x.available_quantity)||0,barcode_id:x.barcode_id,item_sku:x.itemid,category_id:x.category_id,category_name:x.category_name,company_price_total:(Number(x.company_price)||0)*x.quantity,track_inventory:x.track_inventory}));const payload={idempotencyKey:crypto.randomUUID(),items,sales_total:sum,sales_sub_total:subtotal(),extra_discount:Number(b.discount)||0,extra_discount_type:'price',customer_id:b.customer?._id||'',customer_name:b.customer?.name||String(fd.get('customer')||'Client de passage'),cashier_name:state.user?.name||state.user?.username||'',payment_mode:credit>0&&paid===0?'Credit':method,unpaid:paid<=0?'true':'false',partial_check:credit>0?'true':'false',partial_balance:String(paid),payment_pending:String(credit),multi_payment:payments,payment_description:'',sales_description:'',discount_description:'',tax:0,payment_descriptiondiscount:0,extra_discount:Number(b.discount)||0,extra_discount_type:'price'};const result=await post('sales',payload);b.items=[];b.customer=null;b.discount=0;state.drawer=null;render();toast('Vente enregistrée par POSNIC. Référence : '+(result?.sales_id||result?.sale_number||result?._id||'OK'),'success');try{if(window.electronAPI?.printer?.printReceipt)await window.electronAPI.printer.printReceipt(result,{});}catch(printError){toast('Vente enregistrée, mais impression impossible : '+printError.message,'error');}}
let mobileBasketTimer=null,companionStatusTimer=null,mobileBasketBusy=false;
async function pollMobileBasket(){if(!state.user||mobileBasketBusy)return;mobileBasketBusy=true;try{const response=await get('samarina/v1/desktop/basket-jobs');const jobs=Array.isArray(response.rows)?response.rows:[];state.mobileSync='Connecté';const syncStatus=document.querySelector('#mobile-sync-status');if(syncStatus)syncStatus.textContent=state.mobileSync;for(const job of jobs){try{const item=await get('items/'+encodeURIComponent(job.itemId));const added=addItem(item,job.quantity);await post('samarina/v1/desktop/basket-jobs/'+encodeURIComponent(job.id)+'/ack',{state:added?'added':'failed',message:added?'Ajouté au panier actif':'Stock insuffisant'});}catch(error){await post('samarina/v1/desktop/basket-jobs/'+encodeURIComponent(job.id)+'/ack',{state:'failed',message:error.message}).catch(()=>{});}}}catch(error){state.mobileSync='En attente';const syncStatus=document.querySelector('#mobile-sync-status');if(syncStatus)syncStatus.textContent=state.mobileSync;}finally{mobileBasketBusy=false;}}
async function refreshCompanionStatus(){try{const status=await get('samarina/v1/setup/status');state.connectedPhones=Number(status.connectedPhones)||0;state.canPair=status.canPair===true;const count=document.querySelector('#companion-count');if(count)count.textContent='Samarina Companion · '+state.connectedPhones;}catch(_){state.connectedPhones=0;state.canPair=false;}}
function startMobileBasketSync(){if(mobileBasketTimer)clearInterval(mobileBasketTimer);if(companionStatusTimer)clearInterval(companionStatusTimer);pollMobileBasket();refreshCompanionStatus();mobileBasketTimer=setInterval(pollMobileBasket,1800);companionStatusTimer=setInterval(refreshCompanionStatus,15000);}
window.addEventListener('beforeunload',()=>{if(mobileBasketTimer)clearInterval(mobileBasketTimer);if(companionStatusTimer)clearInterval(companionStatusTimer);});
async function render(){if(!state.user){login();return;}const m=current(state);let content='';try{if(state.view==='caisse')content=cashier();else content=await moduleContent();layout(content);}catch(e){layout(head(m.tabs[state.tab]||m.label,'Erreur de chargement')+`<div class="panel"><p class="danger">${esc(e.message)}</p><button class="btn" data-action="refresh">Réessayer</button></div>`);}if(unmountKeyboard)unmountKeyboard();unmountKeyboard=installKeyboard({render,focusSearch});if(state.view==='caisse'){focusSearch();await refreshProductSearch('');}}
async function refreshProductSearch(q){try{searchResults=await loadProducts(q);const host=document.querySelector('#product-results');if(!host)return;host.innerHTML=searchResults.slice(0,12).map(x=>`<button class="quick-item" data-add-item="${esc(x._id)}"><strong>${esc(x.name)}</strong><span class="muted small">${esc(x.itemid||x.barcode_id||'')}</span><b>${money(x.selling_price)} DZD</b><span class="badge">${Number(x.available_quantity)||0} en stock</span></button>`).join('')||'<div class="empty">Aucun article trouvé.</div>';}catch(e){toast(e.message,'error');}}
function openCustomer(){state.drawer={title:'Choisir un client',html:'<input id="customer-search" class="field" placeholder="Nom ou téléphone"><div id="customer-results" class="panel">Recherche des clients…</div>'};render();searchCustomers('');}
async function searchCustomers(q){try{const d=await get('customers/search',{search:q,term:q,limit:30});const list=rowsOf(d);const el=document.querySelector('#customer-results');if(el)el.innerHTML=list.map(x=>`<p><button class="btn" data-customer="${esc(x._id)}">${esc(val(x,'name','customer_name'))} · ${esc(val(x,'phone','customer_phone'))}</button></p>`).join('')||'Aucun client.';state.customerResults=list;}catch(e){toast(e.message,'error');}}
async function handleAction(action,el){if(action==='new-item'){state.drawer={title:'Nouvel article',html:`<form id="new-item-form" class="form-grid"><div class="form-field full"><label>Nom de l’article</label><input class="field" name="name" required></div><div class="form-field"><label>SKU / Référence</label><input class="field" name="itemid"></div><div class="form-field"><label>Code-barres (vide = génération automatique)</label><input class="field" name="barcode_id"></div><div class="form-field"><label>Catégorie</label><input class="field" name="category_name"></div><div class="form-field"><label>Marque</label><input class="field" name="brand"></div><div class="form-field"><label>Fournisseur</label><input class="field" name="supplier_name"></div><div class="form-field"><label>Coût EUR</label><input class="field" name="purchase_price_eur" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>Coût DZD</label><input class="field" name="company_price" type="number" min="0" step=".01" value="0"></div><div class="form-field"><label>Prix de vente DZD</label><input class="field" name="selling_price" type="number" min="0" step=".01" required></div><div class="form-field"><label>Stock initial</label><input class="field" name="available_quantity" type="number" min="0" step=".001" value="0"></div><div class="form-field"><label>Seuil stock faible</label><input class="field" name="low_stock_alert" type="number" min="0" value="5"></div><div class="form-field"><label><input type="checkbox" name="track_inventory" checked> Suivre le stock</label></div><div class="form-field full"><button class="btn primary">Créer l’article</button></div></form>`};render();}else if(action==='clear-label-queue'){state.labelQueue=[];render();}else if(action==='backup-now'){const result=await window.electronAPI.backup.runBackupNow(true);toast(result?.message||'Sauvegarde MongoDB terminée.','success');}else if(action==='test-printer'){const settings=await window.electronAPI.printer.getReceiptSettings();await window.electronAPI.printer.testReceipt(settings||{});toast('Test ticket envoyé à l’imprimante.','success');}else if(action==='test-zr'){const credentials=await window.electronAPI.zr.getCredentials();const catalog=await window.electronAPI.zr.catalog(credentials);toast('Connexion ZR Express OK · '+(catalog.wilayas?.length||0)+' wilayas et '+(catalog.hubs?.length||0)+' bureaux.','success');}else if(action==='save-label-template'){const payload={width:Number(document.querySelector('#label-width')?.value)||30,height:Number(document.querySelector('#label-height')?.value)||45,copies:Number(document.querySelector('#label-copies')?.value)||1,showName:document.querySelector('#label-show-name')?.checked!==false,showPrice:document.querySelector('#label-show-price')?.checked!==false,showBarcode:document.querySelector('#label-show-barcode')?.checked!==false};await put('posnic-next/settings/label-template',payload);toast('Modèle d’étiquette enregistré.','success');}else if(action==='new-customer'){state.drawer={title:'Nouveau client',html:`<form id="customer-form" class="form-grid"><div class="form-field full"><label>Nom complet</label><input class="field" name="name" required></div><div class="form-field"><label>Téléphone</label><input class="field" name="phone"></div><div class="form-field"><label>E-mail</label><input class="field" name="email" type="email"></div><div class="form-field"><label>Ville</label><input class="field" name="city"></div><div class="form-field"><label>Palier de prix</label><select class="field" name="price_tier"><option value="1">Prix 1</option><option value="2">Prix 2</option><option value="3">Prix 3</option></select></div><div class="form-field full"><label>Adresse</label><input class="field" name="address"></div><div class="form-field full"><button class="btn primary">Créer le client</button></div></form>`};render();}else if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('sm-theme',state.theme);render();}else if(action==='collapse'){state.expanded=!state.expanded;render();}else if(action==='new-basket'){const id=Math.max(...state.baskets.map(x=>x.id))+1;state.baskets.push({id,name:'Panier '+id,customer:null,items:[]});state.activeBasket=id;render();}else if(action==='F1'){state.drawer={title:'Paiement espèces',html:`<p>Total : <b>${money(total())} DZD</b></p><form id="checkout-form" class="form-grid"><input type="hidden" name="method" value="Cash"><div class="form-field full"><label>Montant reçu</label><input class="field" name="paid" type="number" min="0" step=".01" value="${total()}" required></div><div class="form-field full"><button class="btn primary">Valider espèces</button></div></form>`};render();}else if(action==='F2')paymentDrawer();else if(action==='F3'||action==='customer')openCustomer();else if(action==='F4'){state.drawer={title:'Remise globale',html:'<form id="discount-form" class="form-grid"><div class="form-field"><label>Remise DZD</label><input class="field" name="discount" type="number" min="0" step=".01" required></div><div class="form-field full"><button class="btn primary">Appliquer</button></div></form>'};render();}else if(action==='F7'){state.view='zr-express';state.tab=1;state.drawer=null;render();}else if(action==='F8'){state.drawer={title:'Retour / échange ticket',html:'<form id="return-lookup" class="form-grid"><div class="form-field full"><label>ID du ticket POSNIC</label><input class="field" name="sale_id" required></div><div class="form-field full"><button class="btn primary">Charger le ticket</button></div></form>'};render();}else if(action==='close'){state.drawer=null;render();focusSearch();}else if(action==='backdrop'&&el.target.classList.contains('drawer-backdrop')){state.drawer=null;render();}else if(action==='refresh'){render();}else if(action==='companion'){state.drawer={title:'Samarina Companion',html:`<p><b>${state.connectedPhones}</b> téléphone(s) connecté(s) à ce magasin.</p><p class="muted">Les articles envoyés depuis le téléphone arrivent dans le panier actif du poste.</p><div class="actions"><button class="btn primary" data-action="create-pair-code" ${state.canPair?'':'disabled'}>Générer QR de jumelage</button><button class="btn" data-action="open-mobile">Ouvrir le compagnon</button></div>`};render();}else if(action==='open-mobile'){window.open('/mobile/','_blank','noopener');}else if(action==='create-pair-code'){await get('samarina/v1/setup/status');const result=await post('samarina/v1/setup/pairing-code',{});const images=(result.pairingQr||[]).map(x=>`<div class="panel"><img alt="QR de jumelage Samarina" width="220" height="220" src="${/^data:image\/png;base64,/.test(x.qr||'')?x.qr:''}"><p>${esc(x.url)}</p></div>`).join('');state.drawer={title:'Jumeler un téléphone · expire dans 5 minutes',html:`<h2>${esc(result.code)}</h2><p>Magasin : ${esc(result.branch)}</p><div class="quick-grid">${images}</div><p class="muted">Scannez le QR avec le téléphone à connecter.</p>`};render();}else if(action==='print-label'){printLabel();}}
function printLabel(){const manual={name:document.querySelector('#label-name')?.value||'',selling_price:document.querySelector('#label-price')?.value||'',barcode_id:document.querySelector('#label-code')?.value||''};const queue=state.labelQueue.length?state.labelQueue:[manual];if(!queue.length||(!state.labelQueue.length&&(!manual.name||!manual.selling_price)))throw new Error('Ajoutez des articles à la file ou saisissez un nom et un prix.');const copies=Math.max(1,Math.min(100,Number(document.querySelector('#label-copies')?.value)||1)),w=Math.max(20,Number(document.querySelector('#label-width')?.value)||30),h=Math.max(20,Number(document.querySelector('#label-height')?.value)||45),showName=document.querySelector('#label-show-name')?.checked!==false,showPrice=document.querySelector('#label-show-price')?.checked!==false,showBarcode=document.querySelector('#label-show-barcode')?.checked!==false;const labels=queue.flatMap(item=>Array.from({length:copies},()=>'<div class="label">'+(showName?'<div class="name">'+esc(item.name||'')+'</div>':'')+(showPrice?'<div class="price">'+esc(item.selling_price||item.sell_price||'')+' DZD</div>':'')+(showBarcode?'<div class="code">'+esc(item.barcode_id||item.itemid||'')+'</div>':'')+'</div>')).join('');const win=window.open('','_blank','width=500,height=700');if(!win)throw new Error('Autorisez la fenêtre d’impression.');win.document.write('<!doctype html><html><head><title>Étiquettes Saint Marina</title><style>@page{size:'+w+'mm '+h+'mm;margin:1mm}body{font-family:Arial;margin:0}.label{height:'+(h-2)+'mm;display:flex;flex-direction:column;align-items:center;justify-content:center;page-break-after:always;border:1px solid #ddd}.name{font-size:12pt;font-weight:bold}.price{font-size:18pt;font-weight:bold}.code{font-size:9pt;letter-spacing:1px}</style></head><body>'+labels+'<script>window.onload=()=>window.print()</script></body></html>');win.document.close();}
root.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;try{if(el.dataset.view){state.view=el.dataset.view;state.tab=0;state.query='';state.drawer=null;location.hash=state.view;await render();return;}if(el.dataset.tab!==undefined){state.tab=Number(el.dataset.tab);await render();return;}if(el.dataset.basket){state.activeBasket=Number(el.dataset.basket);render();return;}if(el.dataset.addItem){const item=searchResults.find(x=>String(x._id)===el.dataset.addItem);if(item)addItem(item);return;}if(el.dataset.qty){const item=basket().items.find(x=>String(x._id)===el.dataset.id);if(item){const next=item.quantity+Number(el.dataset.qty),available=Number(item.available_quantity);if(Number(el.dataset.qty)>0&&item.track_inventory&&!item.negative_stock&&Number.isFinite(available)&&next>available){toast('Stock insuffisant.','error');return;}item.quantity=Math.max(1,next);render();}return;}if(el.dataset.remove){basket().items=basket().items.filter(x=>String(x._id)!==el.dataset.remove);render();return;}if(el.dataset.customer){const item=(state.customerResults||[]).find(x=>String(x._id)===el.dataset.customer);if(item)basket().customer={_id:item._id,name:item.name||item.customer_name,debt:item.balance||item.outstanding||0};state.drawer=null;render();return;}if(el.dataset.loadReturnSale){const sale=await get('sales/'+encodeURIComponent(document.querySelector('[name=sale_id]')?.value||''));state.returnSale=sale;state.drawer={title:'Retour ticket · '+esc(sale.sales_id||sale.sale_number||sale._id),html:returnSaleForm(sale)};render();return;}if(el.dataset.remind){await post('credit/reminder/'+encodeURIComponent(el.dataset.remind),{});toast('Relance WhatsApp envoyée.','success');return;}if(el.dataset.whatsappSale){await post('whatsapp/send-receipt',{sale_id:el.dataset.whatsappSale,phone_number:el.dataset.phone||''});toast('Ticket envoyé sur WhatsApp.','success');return;}if(el.dataset.printSale){const sale=await get('sales/'+el.dataset.printSale);if(!window.electronAPI?.printer?.printReceipt)throw new Error('Impression ESC/POS disponible uniquement sur le poste POSNIC.');await window.electronAPI.printer.printReceipt(sale,{});toast('Ticket envoyé à l’imprimante.','success');return;}if(el.dataset.zrStatus){await patch('delivery-zr/'+encodeURIComponent(el.dataset.zrStatus)+'/status',{status:'LIVRE'});toast('Statut ZR Express mis à jour.','success');render();return;}if(el.dataset.settle){state.drawer={title:'Encaisser un versement',html:`<form id="settle-form" data-customer-id="${esc(el.dataset.settle)}" class="form-grid"><div class="form-field"><label>Montant DZD</label><input class="field" name="amount" type="number" min=".01" step=".01" required></div><div class="form-field"><label>Mode</label><select class="field" name="method"><option>Cash</option><option>BaridiMob</option></select></div><div class="form-field full"><button class="btn primary">Enregistrer le versement</button></div></form>`};render();return;}if(el.dataset.revoke){await post('handsets/'+encodeURIComponent(el.dataset.revoke)+'/revoke',{});toast('Appareil révoqué.','success');render();return;}if(el.dataset.zrCancel){await post('delivery-zr/'+encodeURIComponent(el.dataset.zrCancel)+'/cancel',{});toast('Demande d’annulation envoyée.','success');render();return;}if(el.dataset.queueLabel){const item=state.records.find(x=>String(x._id)===el.dataset.queueLabel);if(item){state.labelQueue.push(item);toast('Article ajouté à la file d’étiquettes.','success');}return;}if(el.dataset.editItem){const item=await get('items/'+el.dataset.editItem);state.drawer={title:'Modifier un article',html:`<form id="item-form" data-id="${esc(item._id)}" class="form-grid"><div class="form-field full"><label>Nom</label><input class="field" name="name" value="${esc(item.name)}" required></div><div class="form-field"><label>SKU</label><input class="field" name="itemid" value="${esc(item.itemid)}"></div><div class="form-field"><label>Code-barres</label><input class="field" name="barcode_id" value="${esc(item.barcode_id)}"></div><div class="form-field"><label>Prix vente DZD</label><input class="field" name="selling_price" type="number" value="${Number(item.selling_price)||0}"></div><div class="form-field"><label>Stock</label><input class="field" name="available_quantity" type="number" value="${Number(item.available_quantity)||0}"></div><div class="form-field full"><button class="btn primary">Enregistrer l’article</button></div></form>`};render();return;}await handleAction(el.dataset.action,el);}catch(err){toast(err.message,'error');}});
root.addEventListener('click',e=>{const row=e.target.closest('[data-cart-row]');if(row){document.querySelectorAll('[data-cart-row]').forEach(x=>x.classList.remove('selected'));row.classList.add('selected');}});
root.addEventListener('posnic:refresh',()=>render());
root.addEventListener('keydown',async e=>{if(e.target.id==='barcode-search'&&e.key==='Enter'){e.preventDefault();const q=e.target.value.trim();if(!q)return;try{const matches=await loadProducts(q);if(matches.length===1||matches.length>0){addItem(matches[0]);e.target.value='';refreshProductSearch('');}}catch(err){toast(err.message,'error');}}});
root.addEventListener('input',e=>{if(e.target.classList.contains('denomination')){const total=[2000,1000,500,200,100].reduce((sum,value)=>sum+value*(Number(document.querySelector('[name=denom_'+value+']')?.value)||0),0);const out=document.querySelector('#counted-cash');if(out)out.textContent=money(total);}if(e.target.id==='barcode-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>refreshProductSearch(e.target.value),120);}if(e.target.id==='list-search'){state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>render(),250);}if(e.target.id==='customer-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>searchCustomers(e.target.value),200);}});
root.querySelector('#global-search')?.addEventListener('keydown',e=>{if(e.key==='Enter'){state.query=e.target.value;state.view='catalogue';state.tab=0;state.drawer=null;location.hash='catalogue';render();}});
root.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('form'))return;e.preventDefault();const fd=new FormData(form);try{if(form.id==='login-form'){await post('auth/login',{username:fd.get('username'),password:fd.get('password')});state.user=await get('auth/me');toast('Connexion réussie.','success');render();}else if(form.id==='return-lookup'){const id=String(fd.get('sale_id')||'').trim();const sale=await get('sales/'+encodeURIComponent(id));state.returnSale=sale;state.drawer={title:'Retour ticket · '+(sale.sales_id||sale.sale_number||sale._id),html:returnSaleForm(sale)};render();}else if(form.id==='return-form'){const sale=state.returnSale;if(!sale)throw new Error('Aucun ticket chargé.');const returnItems=(sale.items||[]).map((line,index)=>{const qty=Math.max(0,Number(document.querySelector('[name=return_qty_'+index+']')?.value)||0);if(!qty)return null;const originalQty=Math.max(1,Number(line.item_quantity)||1),lineTotal=Number(line.total_amount)||originalQty*(Number(line.item_price)||0);return {item_id:line.item_id||line.item||line.id,item_name:line.item_name||line.name,item_quantity:qty,item_price:Number(line.item_price)||0,total_amount:Math.round((lineTotal/originalQty)*qty*100)/100,item_unit:line.item_unit||'qty',tax:line.tax,tax_type:line.tax_type,igst_tax:line.igst_tax,cgst_tax:line.cgst_tax,sgst_tax:line.sgst_tax};}).filter(Boolean);if(!returnItems.length)throw new Error('Indiquez au moins une quantité à retourner.');const result=await post('sales/returnSales',{sales_id:sale._id||sale.sales_id,items:sale.items||[],items_return:returnItems,refund_method:fd.get('refund_method'),reason:fd.get('reason'),partial_check:String(sale.partial_check||'false'),payment_pending:Number(sale.payment_pending)||0,extra_discount:0,extra_discount_type:'price'});state.drawer=null;state.returnSale=null;toast('Retour enregistré · '+money(result?.return_amount||returnItems.reduce((n,x)=>n+x.total_amount,0))+' DZD','success');render();}else if(form.id==='checkout-form'){await checkout(form);}else if(form.id==='close-form'){const body=Object.fromEntries(fd.entries());const counted_cash=[2000,1000,500,200,100].reduce((sum,value)=>sum+value*(Number(body['denom_'+value])||0),0);const result=await post('sales/cashierDayClose',{date:body.date,counted_cash});toast('Clôture enregistrée. Écart : '+money(result?.difference)+' DZD','success');render();}else if(form.id==='customer-form'){const body=Object.fromEntries(fd.entries());body.price_tier=Number(body.price_tier)||1;await post('customers',body);state.drawer=null;toast('Client créé.','success');render();}else if(form.id==='zr-settings-form'){await window.electronAPI.zr.saveCredentials({tenantId:fd.get('tenantId'),apiKey:fd.get('apiKey')});toast('Identifiants ZR Express enregistrés de façon chiffrée.','success');render();}else if(form.id==='printer-form'){await window.electronAPI.printer.setDefault(fd.get('printer'));toast('Imprimante par défaut mise à jour.','success');}else if(form.id==='general-settings-form'){const body=Object.fromEntries(fd.entries());await put('settings/general',body);await post('settings/updateThemeSettings',{theme:body.theme});state.theme=body.theme;localStorage.setItem('sm-theme',state.theme);toast('Informations boutique et thème enregistrés.','success');render();}else if(form.id==='costing-form'){const body=Object.fromEntries(fd.entries());try{body.cipherMap=JSON.parse(body.cipherMap||'{}');}catch{throw new Error('Le chiffrement doit être un JSON valide.');}body.exchangeRate=Number(body.exchangeRate);body.markupPercent=Number(body.markupPercent);await put('posnic-next/settings/costing',body);toast('Règles EUR → DZD enregistrées.','success');render();}else if(form.id==='cost-preview'){const rate=Number(document.querySelector('[name=exchangeRate]')?.value)||280,markup=Number(document.querySelector('[name=markupPercent]')?.value)||0,rounding=document.querySelector('[name=rounding]')?.value||'none';let price=(Number(fd.get('eur'))||0)*rate+(Number(fd.get('extra'))||0);price*=1+markup/100;if(rounding==='50')price=Math.ceil(price/50)*50;if(rounding==='100')price=Math.ceil(price/100)*100;if(rounding==='x900')price=Math.floor(price/1000)*1000+900;if(rounding==='x950')price=Math.floor(price/1000)*1000+950;document.querySelector('#cost-preview-result').textContent=money(price)+' DZD';}else if(form.id==='zr-form'){const body=Object.fromEntries(fd.entries());const sale=await get('sales/'+body.saleId);const credentials=await window.electronAPI.zr.getCredentials();const parcel=await window.electronAPI.zr.createParcel(credentials,{customerName:body.customerName,phone:body.phone,cityTerritoryId:body.cityTerritoryId,districtTerritoryId:body.districtTerritoryId,address:body.address,deliveryType:body.deliveryType==='pickup-point'?'pickup-point':'home',sourceHubId:body.sourceHubId,deliveryFee:Number(body.deliveryFee)||0,codTotal:Number(body.codTotal)||0,description:body.description,items:(sale.items||[]).map(x=>({name:x.item_name||x.name,unitPrice:Number(x.item_price||x.unit_price||0),quantity:Number(x.item_quantity||x.quantity||1)}))});await post('delivery-zr/link',{saleId:body.saleId,parcel,recipientName:body.customerName,recipientPhone:body.phone,wilaya:body.cityTerritoryId,commune:body.districtTerritoryId,deliveryType:body.deliveryType,deliveryFee:Number(body.deliveryFee)||0,codTotal:Number(body.codTotal)||0,address:body.address});toast('Colis créé et lié au ticket POSNIC : '+parcel.trackingNumber,'success');render();}else if(form.id==='new-item-form'){const body=Object.fromEntries(fd.entries());for(const k of ['purchase_price_eur','company_price','selling_price','available_quantity','low_stock_alert'])body[k]=Number(body[k])||0;body.track_inventory=form.querySelector('[name=track_inventory]').checked;body.purchase_exchange_rate=Number((await get('posnic-next/settings/costing')).exchangeRate)||280;await post('items',body);state.drawer=null;toast('Article créé.','success');render();}else if(form.id==='item-form'){const body=Object.fromEntries(fd.entries());body.selling_price=Number(body.selling_price)||0;body.available_quantity=Number(body.available_quantity)||0;await put('items/'+form.dataset.id,body);state.drawer=null;toast('Article mis à jour.','success');render();}else if(form.id==='receiving-form'){const body=Object.fromEntries(fd.entries());const supplier=form.querySelector('[name=supplier_id] option:checked');body.supplier_name=supplier?.dataset.name||supplier?.textContent||'';body.supplier_address=supplier?.dataset.address||'';body.supplier_phone=supplier?.dataset.phone||'';body.items=[{item_id:body.item_id,item_quantity:Number(body.item_quantity),item_tax:Number(body.item_tax)||0,item_unit:'qty'}];delete body.item_id;delete body.item_quantity;delete body.item_tax;await post('receivings',body);toast('Réception créée.','success');render();}else if(form.id==='zr-form'){await post('delivery-zr/customer',Object.fromEntries(fd.entries()));toast('Client ZR Express créé / vérifié.','success');render();}else if(form.id==='settle-form'){await post('credit/settle/'+encodeURIComponent(form.dataset.customerId),{amount:Number(fd.get('amount')),payment_mode:fd.get('method'),method:fd.get('method')});state.drawer=null;toast('Versement enregistré.','success');render();}else if(form.id==='discount-form'){const discount=Math.max(0,Number(fd.get('discount'))||0);basket().discount=discount;state.drawer=null;toast('Remise enregistrée sur le panier.','success');render();}else if(form.id==='theme-form'){await post('settings/updateThemeSettings',{theme:fd.get('theme')});toast('Thème enregistré.','success');}else if(form.id==='whatsapp-send'){await post('whatsapp/sendMessage',{phone:fd.get('phone'),message:fd.get('message')});toast('Message WhatsApp envoyé.','success');}}catch(err){toast(err.message,'error');}});
async function boot(){const ok=await checkSession();if(ok){state.view=location.hash.slice(1)||'caisse';startMobileBasketSync();await render();}else login();}
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(modules.some(x=>x.id===id)){state.view=id;state.tab=0;render();}});
boot();
